"""Gift success branches confirmed after receipt and control-flow review."""
ROWS = []
def add(key, labels, subject, lines):
    replies = [line.strip() for line in lines.split('|')]
    assert len(replies) == 11, (key, len(replies))
    ROWS.append(dict(key='hoenn_lastgift_' + key, labels=labels.split(), subject=subject, replies=replies))

add('lanette_doll','Route114_LanettesHouse_Text_EverythingClutteredKeepThis','Lanette is embarrassed by research clutter and gives a doll while asking for discretion; success ends after ignored decoration receipt.','''soft_smile~Her research made a nest. The doll is lovely, but the secret was safe already.|A busy work area is hardly a scandal. No payment for discretion was necessary.|Her house, her business. We do not need a gift to keep quiet.|I would be embarrassed about my own clutter too. We can be kind.|A little mess happens when someone gets absorbed in work.|An earnest researcher has attempted to purchase our silence with a small doll.|The room contains evidence of thinking. A grave and entirely forgivable offense.|I recognize that particular arrangement of an unfinished project.|We need not carry an awkward moment farther than this room.|A cluttered workspace is no reason to make someone feel exposed.|I would thank her and put away any thought of making this a story.''')
add('contest_prize','LilycoveCity_ContestLobby_Text_PokemonWonWeHavePrize','A receptionist congratulates the winning Pokemon and gives the pending prize; terminal on successful prize pickup.','''soft_smile~Our partner won! I hope they know the congratulations are for them too.|A result worth enjoying, and a well organized way to collect the reward.|Good work from our partner. Give them some credit.|Hearing the official congratulations makes it feel real again.|A little celebration for the partner who worked so hard.|The victory has acquired both formal recognition and something to carry home.|Our partner's triumph has successfully completed its administrative phase.|The preparation paid off. It is nice to see that acknowledged.|A pleased little moment deserves time before the next challenge.|A prize is lovely, but that proud partner is the best part.|I would remember our Pokemon's reaction when the congratulations arrive.''')
add('shard_trade_done','Route124_DivingTreasureHuntersHouse_Text_ItsADeal','The treasure hunter confirms a completed shard trade; terminal when the player has no further shards.','''soft_smile~Our little shard has become something useful. A tidy treasure exchange.|The exchange is complete. We can consider how best to use the result.|Fair trade. Keep the new item safe.|I like leaving with the arrangement clearly settled.|A useful find feels even better when it leads to something we need.|The treasure's story has moved neatly into another pair of hands.|One little fragment has negotiated an impressively complete future.|Good to know exactly what we gained from the exchange.|Something found can become the beginning of another useful thing.|A well chosen exchange makes the search feel worthwhile.|I would ask what the hunter plans to do with the shard.''')
add('effort_ribbon','SlateportCity_Text_PleaseGiveItThisEffortRibbon','A woman recognizes the Pokemons extraordinary effort with an Effort Ribbon; root whitelists both named success receipts afterward.','''soft_smile~A ribbon for working so hard. Our friend deserves a very proud little moment.|Recognition for sustained effort is a meaningful kind of reward.|They earned it. Make sure our partner gets the thanks.|I like a ribbon that notices the work behind the result.|All those little days of effort have become something they can wear.|The quiet accumulation of hard work has finally received a visible tribute.|A ribbon for persistence. I rather like that kind of ornament.|Consistent practice can be hard to see until someone recognizes it.|Effort leaves its marks. This one happens to be lovely.|That ribbon belongs with a proud partner and a proper compliment.|I would love to remember how our Pokemon looks wearing it.''')

add('shared_bag_full','gText_TooBadBagIsFull','A shared NPC gift or purchase failure says the bag is full; reply applies only where no later conversation replaces it.','''soft_smile~The bag has reached its maximum amount of yes. Time to find one little space.|The immediate problem is capacity. A little sorting should resolve it.|Bag is full. Make room before trying again.|At least the reason is clear. We can sort it out quietly.|We can clear a little room before asking for anything else.|Our eager collecting has met the entirely reasonable limits of the bag.|The bag has declined further responsibility until we become more organized.|Check what we are carrying before repeating the same attempt.|A little empty space can make the next small kindness easier to receive.|An edit to the bag would improve the whole arrangement.|I would make room first, then return to finish what we started.''')
